const TOPICS={
sintassi:`SINTASSI DI hsh
hsh è un linguaggio di shell compatibile con bash.
  comando arg…          esegue un comando
  a; b                  comandi in sequenza        a && b   b solo se a riesce
  a || b                b solo se a fallisce       a | b    l'output di a diventa l'input di b
  a &                   esegue a in background     ! a      nega lo stato di uscita
  ( … )                 subshell                   { …; }   gruppo nella shell corrente
  # commento            fino a fine riga           \\        continua sulla riga successiva
  'testo'               letterale                  "testo"  espande $variabili e $(…)
  $'a\\tb'               sequenze di escape in stile C
  cmd <<EOF … EOF       here-document (<<-EOF toglie i tab, <<'EOF' senza espansioni)
  cmd <<< "testo"       here-string
  <(cmd)  >(cmd)        sostituzione di processo`,
variabili:`VARIABILI
  x=5   nome="a b"      assegnamento (niente spazi attorno a =)
  export x              rende x visibile ai comandi lanciati      local x   variabile locale in una funzione
  readonly x   unset x  sola lettura / elimina                    declare -i n   intero    declare -u/-l   maiuscolo/minuscolo
  arr=(a b c)           array      \${arr[1]}  \${arr[@]}  \${#arr[@]}  \${!arr[@]}  arr+=(d)
  declare -A m          array associativo:  m[chiave]=valore   \${m[chiave]}  \${!m[@]}
  Speciali: $? stato   $$ pid   $! ultimo bg   $# n. argomenti   $@ $* argomenti   $0 nome   $1…   $_ ultimo argomento
            $RANDOM  $SECONDS  $LINENO  $PWD  $OLDPWD  $HOME  $USER  $PATH  $IFS  $PS1  $COLUMNS  $LINES  $EPOCHSECONDS`,
espansioni:`ESPANSIONI (nell'ordine in cui vengono applicate)
  {a,b,c}  {1..10}  {a..e}  {01..10..3}     graffe
  ~  ~/dir                                   tilde
  $x  \${x}  \${x:-def}  \${x:=def}  \${x:+alt}  \${x:?errore}
  \${#x}  \${x:2:3}  \${x#pref}  \${x##pref}  \${x%suff}  \${x%%suff}
  \${x/vecchio/nuovo}  \${x//vecchio/nuovo}  \${x^}  \${x^^}  \${x,}  \${x,,}  \${!nome}  \${x@Q}
  $(comando)  \`comando\`                      sostituzione di comando
  $((a+b*2))                                 aritmetica
  *  ?  [a-z]  [!abc]  **  e le classi [[:alpha:]]   globbing sui file`,
aritmetica:`ARITMETICA   $((…))   ((…))   let   declare -i
  Operatori: + - * / % ** ++ -- += -= *= /= %= <<= >>= &= |= ^=  << >>  < <= > >= == !=  & | ^ ~  && || !  ?:  ,
  Numeri: 255  0xff  0377  2#1010 (base#valore). Le variabili si usano senza $.
  Esempi:   n=$((3*4+1))    ((i++))    if ((n>10)); then echo grande; fi`,
controllo:`STRUTTURE DI CONTROLLO
  if cmd; then … elif cmd; then … else … fi
  for x in a b c; do … done            for ((i=0;i<10;i++)); do … done
  while cmd; do … done                 until cmd; do … done          break [n]  continue [n]
  case $x in a|b) … ;; c*) … ;& *) … ;; esac      (;& prosegue, ;;& continua i confronti)
  select scelta in uno due; do … done
  [[ espr ]]  con  == != =~ < > -z -n -e -f -d -r -w -x -s -L  -eq -ne -lt -le -gt -ge  && || !
  test espr  /  [ espr ]
  time cmd                             misura il tempo di esecuzione`,
funzioni:`FUNZIONI
  nome() { comandi; }       function nome { comandi; }
  Argomenti: $1 $2 … $# $@     return [n]     local var     funzioni ricorsive consentite
