    fatt() { local n=$1; ((n<=1)) && { echo 1; return; }; echo $(( n * $(fatt $((n-1))) )); }
  declare -f nome  mostra la definizione;  unset -f nome  la elimina;  type nome  dice cos'è.`,
redirezioni:`REDIREZIONI E PIPE
  > file    scrive (sovrascrive)     >> file   aggiunge        < file   legge
  2> file   errori su file           2>&1      errori dove va l'output       &> file  output ed errori
