const openTerm=args=>os.ui.window({title:'Terminale',icon:'⌨️',w:800,h:500,render(body,win){new Term(body,win,args||{},config)}});
loadHist();
os.apps.register({id:'terminale',name:'Terminale',icon:'⌨️',color:'#2b303b',open:openTerm});
os.files.handler({ext:['sh','hsh'],open(p){openTerm({run:p,cwd:H.dirn(p)})}});
os.ui.contextMenu('file',c=>{let d=(c&&c.dir)||'/Documenti';try{if(c&&c.paths&&c.paths.length===1){const s=os.fs.stat(c.path);if(s&&s.d)d=c.path}}catch(e){}return{l:'Apri terminale qui',f:()=>os.apps.launch('terminale',{cwd:d})}});
