.hs-scroll{flex:1;min-height:0;overflow-y:auto;overflow-x:hidden;padding:8px 10px;user-select:text;-webkit-user-select:text;cursor:text;scrollbar-width:thin;scrollbar-color:#3a4150 transparent}
.hs-l,.hs-in{white-space:pre-wrap;word-break:break-all;min-height:1.35em}
.hs-cur{outline:1px solid var(--hs-fg);outline-offset:-1px}
.hs-term.f .hs-cur{background:var(--hs-fg);color:var(--hs-bg);outline:0;animation:hsb 1.1s steps(1) infinite}
@keyframes hsb{50%{background:transparent;color:inherit;outline:1px solid var(--hs-fg)}}
.hs-hl{background:#6b5a00;color:#fff;font-weight:400}
.hs-ta{position:absolute;left:0;top:0;width:1px;height:1px;opacity:0;border:0;padding:0;margin:0;resize:none;font-size:16px;pointer-events:none}
.hs-meas{position:absolute;visibility:hidden;white-space:pre;left:-9999px;top:0}
.hs-pg{position:absolute;inset:0;background:var(--hs-bg);display:none;flex-direction:column;z-index:2}
.hs-pgb{flex:1;min-height:0;overflow:hidden;padding:8px 10px;white-space:pre;user-select:text}
.hs-pgb .hs-l{white-space:pre;word-break:normal}
.hs-pgs{background:var(--hs-fg);color:var(--hs-bg);padding:2px 10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.hs-c:empty{display:none}
